alter table public.avuhz_idempotency_records add column if not exists idempotency_scope text generated always as (case when command_type in ('RecordDiagnosticAgreementAuthority','RecordDiagnosticPaymentVerification','InvalidateDiagnosticPaymentVerification') then 'COMMAND' else 'SUBJECT:' || subject_id::text end) stored; alter table public.avuhz_idempotency_records drop constraint avuhz_idempotency_records_command_type_check, drop constraint avuhz_idempotency_records_subject_type_check, drop constraint avuhz_idempotency_records_tenant_id_trusted_principal_id_co_key; alter table public.avuhz_idempotency_records add constraint avuhz_idempotency_records_command_type_check check (command_type in ('AcceptAcquisitionHandoff','OpenEngagement','SubmitDiagnosticScope','RecordHumanApproval','ApproveDiagnosticScope','CanonicalizeDiagnosticScope','CreateAssessmentAccessProposal','RecordAssessmentAccessApproval','IssueAssessmentAccessGrant','VerifyAssessmentAccess','ExpireAssessmentAccess','RevokeAssessmentAccess','CloseAssessmentAccessForAgreementEnd','RecordDiagnosticAgreementAuthority','RecordDiagnosticPaymentVerification','InvalidateDiagnosticPaymentVerification')), add constraint avuhz_idempotency_records_subject_type_check check (subject_type in ('ACQUISITION_HANDOFF','ENGAGEMENT','DIAGNOSTIC_SCOPE','ASSESSMENT_ACCESS_PROPOSAL','ASSESSMENT_ACCESS_GRANT','DIAGNOSTIC_AGREEMENT_AUTHORITY','DIAGNOSTIC_PAYMENT_VERIFICATION')), add constraint avuhz_idempotency_records_tenant_principal_command_scope_key unique (tenant_id,trusted_principal_id,command_type,subject_type,idempotency_scope,idempotency_key); alter table public.avuhz_lifecycle_events add column if not exists command_id uuid; alter table public.avuhz_lifecycle_events drop constraint avuhz_lifecycle_events_event_type_check, drop constraint avuhz_lifecycle_events_authoritative_subject_type_check; alter table public.avuhz_lifecycle_events add constraint avuhz_lifecycle_events_event_type_check check (event_type in ('engagement.handoff.accepted','engagement.opened','diagnostic_scope.submitted','diagnostic_scope.approved','diagnostic_scope.rejected','human_approval.recorded','diagnostic_scope.canonicalized','assessment_access.proposal_created','assessment_access.approval_recorded','assessment_access.grant_issued','assessment_access.verified_and_activated','assessment_access.expired','assessment_access.revoked','assessment_access.closed','diagnostic_agreement.authority_recorded','diagnostic_payment.verified','diagnostic_payment.invalidated')), add constraint avuhz_lifecycle_events_authoritative_subject_type_check check (authoritative_subject_type in ('ACQUISITION_HANDOFF','ENGAGEMENT','DIAGNOSTIC_SCOPE','ASSESSMENT_ACCESS_PROPOSAL','ASSESSMENT_ACCESS_GRANT','DIAGNOSTIC_AGREEMENT_AUTHORITY','DIAGNOSTIC_PAYMENT_VERIFICATION'));
